import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import {
    Box,
    Paper,
    Typography,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Chip,
    TextField,
    InputAdornment,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Grid,
    Card,
    CardContent,
    LinearProgress,
    IconButton,
    Button,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Tooltip,
    Avatar,
    Pagination,
    Alert,
} from '@mui/material';
import {
    Search as SearchIcon,
    FilterList as FilterIcon,
    Refresh as RefreshIcon,
    History as HistoryIcon,
    Description as DocumentIcon,
    Person as PersonIcon,
    Gavel as CaseIcon,
    Download as DownloadIcon,
    Visibility as ViewIcon,
    Schedule as TimeIcon,
    Security as SecurityIcon,
    Delete as DeleteIcon,
    CalendarToday as CalendarIcon,
} from '@mui/icons-material';
import { logService } from '../../services/api';
import { toast } from 'react-hot-toast';
import moment from 'moment';
import 'moment/locale/es';

moment.locale('es');

const ActivityLogs = () => {
    const { user } = useAuth();
    const [logs, setLogs] = useState([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [filters, setFilters] = useState({
        accion: '',
        usuario_id: '',
        startDate: '',
        endDate: '',
    });
    const [pagination, setPagination] = useState({
        page: 1,
        limit: 20,
        total: 0,
        totalPages: 0,
    });
    const [stats, setStats] = useState({
        total: 0,
        today: 0,
        users: 0,
        documents: 0,
    });
    const [selectedLog, setSelectedLog] = useState(null);
    const [logDetailDialog, setLogDetailDialog] = useState(false);
    const [deleteDialog, setDeleteDialog] = useState(false);

    useEffect(() => {
        if (user?.rol === 'admin') {
            fetchLogs();
            fetchStats();
        }
    }, [user, pagination.page]);

    useEffect(() => {
        // Reiniciar a página 1 cuando cambian los filtros
        setPagination(prev => ({ ...prev, page: 1 }));
    }, [filters]);

    const fetchLogs = async () => {
        try {
            setLoading(true);

            // En una implementación real: await logService.getActivity({ ...filters, ...pagination })
            // Por ahora, usamos datos de ejemplo
            setTimeout(() => {
                const mockLogs = generateMockLogs();
                const filtered = applyFilters(mockLogs);
                const paginated = applyPagination(filtered);

                setLogs(paginated);
                setPagination(prev => ({
                    ...prev,
                    total: filtered.length,
                    totalPages: Math.ceil(filtered.length / prev.limit),
                }));
                setLoading(false);
            }, 1000);
        } catch (error) {
            toast.error('Error cargando logs');
            setLoading(false);
        }
    };

    const fetchStats = async () => {
        // Datos de ejemplo para estadísticas
        setStats({
            total: 1542,
            today: 42,
            users: 8,
            documents: 127,
        });
    };

    const generateMockLogs = () => {
        const actions = ['login', 'logout', 'abrir', 'editar', 'guardar', 'descargar', 'eliminar', 'subir', 'compartir'];
        const users = [
            { id: 1, nombre: 'Administrador', apellido: 'Sistema', email: 'admin@legal.com' },
            { id: 2, nombre: 'María', apellido: 'González', email: 'maria@legal.com' },
            { id: 3, nombre: 'Carlos', apellido: 'Rodríguez', email: 'carlos@legal.com' },
            { id: 4, nombre: 'Ana', apellido: 'Martínez', email: 'ana@legal.com' },
        ];

        const documents = [
            { id: 1, nombre_original: 'Contrato de Servicios.pdf' },
            { id: 2, nombre_original: 'Demanda Civil.doc' },
            { id: 3, nombre_original: 'Reporte Financiero.xlsx' },
            { id: 4, nombre_original: 'Evidencia Foto.jpg' },
        ];

        const cases = [
            { id: 1, numero_caso: 'LAW-2024-001', titulo: 'Demanda Contractual' },
            { id: 2, numero_caso: 'LAW-2024-002', titulo: 'Reclamación Fianza' },
        ];

        const mockLogs = [];
        const now = new Date();

        for (let i = 1; i <= 100; i++) {
            const user = users[Math.floor(Math.random() * users.length)];
            const action = actions[Math.floor(Math.random() * actions.length)];
            const document = Math.random() > 0.3 ? documents[Math.floor(Math.random() * documents.length)] : null;
            const caso = Math.random() > 0.5 ? cases[Math.floor(Math.random() * cases.length)] : null;

            // Fecha aleatoria en los últimos 30 días
            const date = new Date(now);
            date.setDate(date.getDate() - Math.floor(Math.random() * 30));
            date.setHours(Math.floor(Math.random() * 24));
            date.setMinutes(Math.floor(Math.random() * 60));

            mockLogs.push({
                id: i,
                usuario_id: user.id,
                nombre: user.nombre,
                apellido: user.apellido,
                email: user.email,
                documento_id: document?.id,
                documento_nombre: document?.nombre_original,
                caso_id: caso?.id,
                caso_numero: caso?.numero_caso,
                caso_titulo: caso?.titulo,
                accion: action,
                detalles: getActionDetails(action, document?.nombre_original),
                cambios: Math.random() > 0.7 ? JSON.stringify({ cambios: 'Modificaciones realizadas' }) : null,
                tiempo_inicio: date.toISOString(),
                tiempo_fin: new Date(date.getTime() + Math.random() * 600000).toISOString(), // Hasta 10 minutos después
                duracion_segundos: Math.floor(Math.random() * 600), // Hasta 10 minutos
                direccion_ip: `192.168.1.${Math.floor(Math.random() * 255)}`,
                user_agent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
                fecha_registro: date.toISOString(),
            });
        }

        return mockLogs.sort((a, b) => new Date(b.fecha_registro) - new Date(a.fecha_registro));
    };

    const getActionDetails = (action, documentName) => {
        switch (action) {
            case 'login': return 'Inicio de sesión en el sistema';
            case 'logout': return 'Cierre de sesión';
            case 'abrir': return `Apertura del documento: ${documentName}`;
            case 'editar': return `Edición del documento: ${documentName}`;
            case 'guardar': return `Guardado del documento: ${documentName}`;
            case 'descargar': return `Descarga del documento: ${documentName}`;
            case 'eliminar': return `Eliminación del documento: ${documentName}`;
            case 'subir': return `Subida de nuevo documento: ${documentName}`;
            case 'compartir': return `Compartir documento: ${documentName}`;
            default: return 'Acción realizada';
        }
    };

    const applyFilters = (logsList) => {
        return logsList.filter(log => {
            // Búsqueda general
            if (search && !(
                log.nombre.toLowerCase().includes(search.toLowerCase()) ||
                log.apellido.toLowerCase().includes(search.toLowerCase()) ||
                log.email.toLowerCase().includes(search.toLowerCase()) ||
                log.documento_nombre?.toLowerCase().includes(search.toLowerCase()) ||
                log.caso_numero?.toLowerCase().includes(search.toLowerCase()) ||
                log.detalles?.toLowerCase().includes(search.toLowerCase())
            )) {
                return false;
            }

            // Filtro por acción
            if (filters.accion && log.accion !== filters.accion) {
                return false;
            }

            // Filtro por usuario
            if (filters.usuario_id && log.usuario_id != filters.usuario_id) {
                return false;
            }

            // Filtro por fecha
            if (filters.startDate) {
                const start = new Date(filters.startDate);
                const logDate = new Date(log.fecha_registro);
                if (logDate < start) return false;
            }

            if (filters.endDate) {
                const end = new Date(filters.endDate);
                end.setHours(23, 59, 59, 999); // Fin del día
                const logDate = new Date(log.fecha_registro);
                if (logDate > end) return false;
            }

            return true;
        });
    };

    const applyPagination = (logsList) => {
        const start = (pagination.page - 1) * pagination.limit;
        const end = start + pagination.limit;
        return logsList.slice(start, end);
    };

    const handleSearch = (e) => {
        setSearch(e.target.value);
    };

    const handleFilterChange = (name, value) => {
        setFilters({
            ...filters,
            [name]: value,
        });
    };

    const handleClearFilters = () => {
        setSearch('');
        setFilters({
            accion: '',
            usuario_id: '',
            startDate: '',
            endDate: '',
        });
    };

    const handlePageChange = (event, page) => {
        setPagination(prev => ({ ...prev, page }));
    };

    const handleViewLog = (log) => {
        setSelectedLog(log);
        setLogDetailDialog(true);
    };

    const handleDeleteLogs = () => {
        setDeleteDialog(true);
    };

    const handleDeleteConfirm = async () => {
        try {
            // En una implementación real: await logService.deleteOldLogs()
            toast.success('Logs antiguos eliminados');
            fetchLogs();
            setDeleteDialog(false);
        } catch (error) {
            toast.error('Error eliminando logs');
        }
    };

    const handleExportLogs = () => {
        // Implementar exportación a CSV
        toast.success('Exportación en desarrollo');
    };

    const getActionIcon = (action) => {
        switch (action) {
            case 'login': return '🔓';
            case 'logout': return '🔒';
            case 'abrir': return '📖';
            case 'editar': return '✏️';
            case 'guardar': return '💾';
            case 'descargar': return '⬇️';
            case 'eliminar': return '🗑️';
            case 'subir': return '⬆️';
            case 'compartir': return '↗️';
            default: return '📄';
        }
    };

    const getActionColor = (action) => {
        switch (action) {
            case 'login': return 'success';
            case 'logout': return 'default';
            case 'abrir': return 'info';
            case 'editar': return 'warning';
            case 'guardar': return 'primary';
            case 'descargar': return 'secondary';
            case 'eliminar': return 'error';
            case 'subir': return 'success';
            case 'compartir': return 'info';
            default: return 'default';
        }
    };

    const getActionLabel = (action) => {
        switch (action) {
            case 'login': return 'Login';
            case 'logout': return 'Logout';
            case 'abrir': return 'Abrir';
            case 'editar': return 'Editar';
            case 'guardar': return 'Guardar';
            case 'descargar': return 'Descargar';
            case 'eliminar': return 'Eliminar';
            case 'subir': return 'Subir';
            case 'compartir': return 'Compartir';
            default: return action;
        }
    };

    const formatDuration = (seconds) => {
        if (!seconds) return 'N/A';

        const hours = Math.floor(seconds / 3600);
        const minutes = Math.floor((seconds % 3600) / 60);
        const secs = seconds % 60;

        if (hours > 0) {
            return `${hours}h ${minutes}m`;
        } else if (minutes > 0) {
            return `${minutes}m ${secs}s`;
        } else {
            return `${secs}s`;
        }
    };

    const actionOptions = [
        { value: 'login', label: 'Login' },
        { value: 'logout', label: 'Logout' },
        { value: 'abrir', label: 'Abrir' },
        { value: 'editar', label: 'Editar' },
        { value: 'guardar', label: 'Guardar' },
        { value: 'descargar', label: 'Descargar' },
        { value: 'eliminar', label: 'Eliminar' },
        { value: 'subir', label: 'Subir' },
        { value: 'compartir', label: 'Compartir' },
    ];

    const userOptions = [
        { value: 1, label: 'Administrador Sistema' },
        { value: 2, label: 'María González' },
        { value: 3, label: 'Carlos Rodríguez' },
        { value: 4, label: 'Ana Martínez' },
    ];

    if (user?.rol !== 'admin') {
        return (
            <Box p={3}>
                <Alert severity="error">
                    <Typography variant="h6" gutterBottom>
                        Acceso denegado
                    </Typography>
                    <Typography>
                        Solo los administradores pueden acceder a los logs de auditoría.
                    </Typography>
                </Alert>
            </Box>
        );
    }

    return (
        <Box>
            {/* Header */}
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
                <Box>
                    <Typography variant="h4" fontWeight="bold">
                        Logs de Auditoría
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                        Registro completo de todas las actividades del sistema
                    </Typography>
                </Box>
                <Box display="flex" gap={1}>
                    <Button
                        variant="outlined"
                        startIcon={<DownloadIcon />}
                        onClick={handleExportLogs}
                    >
                        Exportar
                    </Button>
                    <Button
                        variant="outlined"
                        color="error"
                        startIcon={<DeleteIcon />}
                        onClick={handleDeleteLogs}
                    >
                        Limpiar Logs Antiguos
                    </Button>
                </Box>
            </Box>

            {/* Estadísticas */}
            <Grid container spacing={3} mb={4}>
                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Box>
                                    <Typography variant="h4" fontWeight="bold">
                                        {stats.total.toLocaleString()}
                                    </Typography>
                                    <Typography variant="body2" color="textSecondary">
                                        Total de Logs
                                    </Typography>
                                </Box>
                                <HistoryIcon color="primary" sx={{ fontSize: 40 }} />
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Box>
                                    <Typography variant="h4" fontWeight="bold" color="success.main">
                                        {stats.today}
                                    </Typography>
                                    <Typography variant="body2" color="textSecondary">
                                        Hoy
                                    </Typography>
                                </Box>
                                <CalendarIcon color="success" sx={{ fontSize: 40 }} />
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Box>
                                    <Typography variant="h4" fontWeight="bold" color="info.main">
                                        {stats.users}
                                    </Typography>
                                    <Typography variant="body2" color="textSecondary">
                                        Usuarios Activos
                                    </Typography>
                                </Box>
                                <PersonIcon color="info" sx={{ fontSize: 40 }} />
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Box>
                                    <Typography variant="h4" fontWeight="bold" color="warning.main">
                                        {stats.documents}
                                    </Typography>
                                    <Typography variant="body2" color="textSecondary">
                                        Documentos Modificados
                                    </Typography>
                                </Box>
                                <DocumentIcon color="warning" sx={{ fontSize: 40 }} />
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            {/* Filtros */}
            <Paper sx={{ p: 3, mb: 3 }}>
                <Grid container spacing={2} alignItems="center">
                    <Grid item xs={12} md={4}>
                        <TextField
                            fullWidth
                            placeholder="Buscar en logs..."
                            value={search}
                            onChange={handleSearch}
                            InputProps={{
                                startAdornment: (
                                    <InputAdornment position="start">
                                        <SearchIcon />
                                    </InputAdornment>
                                ),
                            }}
                        />
                    </Grid>

                    <Grid item xs={12} md={2}>
                        <FormControl fullWidth>
                            <InputLabel>Acción</InputLabel>
                            <Select
                                value={filters.accion}
                                onChange={(e) => handleFilterChange('accion', e.target.value)}
                                label="Acción"
                            >
                                <MenuItem value="">Todas</MenuItem>
                                {actionOptions.map(option => (
                                    <MenuItem key={option.value} value={option.value}>
                                        {option.label}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Grid>

                    <Grid item xs={12} md={2}>
                        <FormControl fullWidth>
                            <InputLabel>Usuario</InputLabel>
                            <Select
                                value={filters.usuario_id}
                                onChange={(e) => handleFilterChange('usuario_id', e.target.value)}
                                label="Usuario"
                            >
                                <MenuItem value="">Todos</MenuItem>
                                {userOptions.map(option => (
                                    <MenuItem key={option.value} value={option.value}>
                                        {option.label}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Grid>

                    <Grid item xs={12} md={2}>
                        <TextField
                            fullWidth
                            type="date"
                            label="Desde"
                            value={filters.startDate}
                            onChange={(e) => handleFilterChange('startDate', e.target.value)}
                            InputLabelProps={{ shrink: true }}
                        />
                    </Grid>

                    <Grid item xs={12} md={2}>
                        <TextField
                            fullWidth
                            type="date"
                            label="Hasta"
                            value={filters.endDate}
                            onChange={(e) => handleFilterChange('endDate', e.target.value)}
                            InputLabelProps={{ shrink: true }}
                        />
                    </Grid>

                    <Grid item xs={12}>
                        <Box display="flex" gap={1} justifyContent="flex-end">
                            <Button
                                variant="outlined"
                                startIcon={<FilterIcon />}
                                onClick={fetchLogs}
                            >
                                Aplicar Filtros
                            </Button>
                            <Button
                                variant="text"
                                onClick={handleClearFilters}
                            >
                                Limpiar
                            </Button>
                            <IconButton onClick={fetchLogs}>
                                <RefreshIcon />
                            </IconButton>
                        </Box>
                    </Grid>
                </Grid>
            </Paper>

            {/* Tabla de logs */}
            {loading ? (
                <Box display="flex" justifyContent="center" p={4}>
                    <LinearProgress sx={{ width: '100%', maxWidth: 600 }} />
                </Box>
            ) : (
                <>
                    <Paper>
                        <TableContainer>
                            <Table>
                                <TableHead>
                                    <TableRow>
                                        <TableCell>Usuario</TableCell>
                                        <TableCell>Acción</TableCell>
                                        <TableCell>Documento/Caso</TableCell>
                                        <TableCell>Detalles</TableCell>
                                        <TableCell>Duración</TableCell>
                                        <TableCell>IP</TableCell>
                                        <TableCell>Fecha/Hora</TableCell>
                                        <TableCell align="center">Acciones</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {logs.map((log) => (
                                        <TableRow key={log.id} hover>
                                            <TableCell>
                                                <Box display="flex" alignItems="center" gap={2}>
                                                    <Avatar sx={{ width: 32, height: 32, bgcolor: 'primary.main', fontSize: 14 }}>
                                                        {log.nombre.charAt(0)}{log.apellido.charAt(0)}
                                                    </Avatar>
                                                    <Box>
                                                        <Typography variant="body2" fontWeight="medium">
                                                            {log.nombre} {log.apellido}
                                                        </Typography>
                                                        <Typography variant="caption" color="textSecondary">
                                                            {log.email}
                                                        </Typography>
                                                    </Box>
                                                </Box>
                                            </TableCell>
                                            <TableCell>
                                                <Chip
                                                    icon={<span style={{ marginRight: 4 }}>{getActionIcon(log.accion)}</span>}
                                                    label={getActionLabel(log.accion)}
                                                    color={getActionColor(log.accion)}
                                                    size="small"
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Box>
                                                    {log.documento_nombre && (
                                                        <Box display="flex" alignItems="center" gap={1} mb={0.5}>
                                                            <DocumentIcon fontSize="small" color="action" />
                                                            <Typography variant="caption">
                                                                {log.documento_nombre}
                                                            </Typography>
                                                        </Box>
                                                    )}
                                                    {log.caso_numero && (
                                                        <Box display="flex" alignItems="center" gap={1}>
                                                            <CaseIcon fontSize="small" color="action" />
                                                            <Typography variant="caption">
                                                                {log.caso_numero}
                                                            </Typography>
                                                        </Box>
                                                    )}
                                                </Box>
                                            </TableCell>
                                            <TableCell>
                                                <Typography variant="body2">
                                                    {log.detalles}
                                                </Typography>
                                            </TableCell>
                                            <TableCell>
                                                {log.duracion_segundos ? (
                                                    <Chip
                                                        label={formatDuration(log.duracion_segundos)}
                                                        size="small"
                                                        variant="outlined"
                                                    />
                                                ) : (
                                                    <Typography variant="caption" color="textSecondary">
                                                        N/A
                                                    </Typography>
                                                )}
                                            </TableCell>
                                            <TableCell>
                                                <Typography variant="caption" fontFamily="monospace">
                                                    {log.direccion_ip}
                                                </Typography>
                                            </TableCell>
                                            <TableCell>
                                                <Box>
                                                    <Typography variant="body2">
                                                        {moment(log.fecha_registro).format('DD/MM/YYYY')}
                                                    </Typography>
                                                    <Typography variant="caption" color="textSecondary">
                                                        {moment(log.fecha_registro).format('HH:mm:ss')}
                                                    </Typography>
                                                </Box>
                                            </TableCell>
                                            <TableCell align="center">
                                                <Tooltip title="Ver detalles">
                                                    <IconButton
                                                        size="small"
                                                        onClick={() => handleViewLog(log)}
                                                    >
                                                        <ViewIcon fontSize="small" />
                                                    </IconButton>
                                                </Tooltip>
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>

                        {logs.length === 0 && (
                            <Box p={4} textAlign="center">
                                <Typography variant="h6" color="textSecondary" gutterBottom>
                                    No se encontraron logs
                                </Typography>
                                <Typography variant="body2" color="textSecondary">
                                    Intenta con otros filtros de búsqueda
                                </Typography>
                            </Box>
                        )}
                    </Paper>

                    {/* Paginación */}
                    {pagination.totalPages > 1 && (
                        <Box display="flex" justifyContent="center" mt={3}>
                            <Pagination
                                count={pagination.totalPages}
                                page={pagination.page}
                                onChange={handlePageChange}
                                color="primary"
                                showFirstButton
                                showLastButton
                            />
                        </Box>
                    )}
                </>
            )}

            {/* Diálogo de detalles del log */}
            <Dialog open={logDetailDialog} onClose={() => setLogDetailDialog(false)} maxWidth="md" fullWidth>
                <DialogTitle>
                    <Box display="flex" alignItems="center" gap={1}>
                        <HistoryIcon />
                        Detalles del Log
                    </Box>
                </DialogTitle>
                <DialogContent>
                    {selectedLog && (
                        <Box sx={{ pt: 2 }}>
                            <Grid container spacing={3}>
                                <Grid item xs={12}>
                                    <Typography variant="subtitle2" gutterBottom>
                                        Información General
                                    </Typography>
                                    <Paper variant="outlined" sx={{ p: 2 }}>
                                        <Grid container spacing={2}>
                                            <Grid item xs={12} md={6}>
                                                <Typography variant="caption" color="textSecondary" display="block">
                                                    ID del Log
                                                </Typography>
                                                <Typography variant="body2">
                                                    {selectedLog.id}
                                                </Typography>
                                            </Grid>
                                            <Grid item xs={12} md={6}>
                                                <Typography variant="caption" color="textSecondary" display="block">
                                                    Fecha y Hora
                                                </Typography>
                                                <Typography variant="body2">
                                                    {moment(selectedLog.fecha_registro).format('LLL')}
                                                </Typography>
                                            </Grid>
                                        </Grid>
                                    </Paper>
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <Typography variant="subtitle2" gutterBottom>
                                        Usuario
                                    </Typography>
                                    <Paper variant="outlined" sx={{ p: 2 }}>
                                        <Box display="flex" alignItems="center" gap={2}>
                                            <Avatar sx={{ bgcolor: 'primary.main' }}>
                                                {selectedLog.nombre.charAt(0)}{selectedLog.apellido.charAt(0)}
                                            </Avatar>
                                            <Box>
                                                <Typography variant="body2" fontWeight="medium">
                                                    {selectedLog.nombre} {selectedLog.apellido}
                                                </Typography>
                                                <Typography variant="caption" color="textSecondary">
                                                    {selectedLog.email}
                                                </Typography>
                                            </Box>
                                        </Box>
                                    </Paper>
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <Typography variant="subtitle2" gutterBottom>
                                        Acción
                                    </Typography>
                                    <Paper variant="outlined" sx={{ p: 2 }}>
                                        <Box display="flex" alignItems="center" justifyContent="space-between">
                                            <Box>
                                                <Typography variant="body2" fontWeight="medium">
                                                    {getActionLabel(selectedLog.accion)}
                                                </Typography>
                                                <Typography variant="caption" color="textSecondary">
                                                    {selectedLog.detalles}
                                                </Typography>
                                            </Box>
                                            <Chip
                                                label={getActionLabel(selectedLog.accion)}
                                                color={getActionColor(selectedLog.accion)}
                                                size="small"
                                            />
                                        </Box>
                                    </Paper>
                                </Grid>

                                {selectedLog.documento_nombre && (
                                    <Grid item xs={12} md={6}>
                                        <Typography variant="subtitle2" gutterBottom>
                                            Documento
                                        </Typography>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Box display="flex" alignItems="center" gap={1}>
                                                <DocumentIcon color="action" />
                                                <Typography variant="body2">
                                                    {selectedLog.documento_nombre}
                                                </Typography>
                                            </Box>
                                        </Paper>
                                    </Grid>
                                )}

                                {selectedLog.caso_numero && (
                                    <Grid item xs={12} md={6}>
                                        <Typography variant="subtitle2" gutterBottom>
                                            Caso
                                        </Typography>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Box display="flex" alignItems="center" gap={1}>
                                                <CaseIcon color="action" />
                                                <Box>
                                                    <Typography variant="body2">
                                                        {selectedLog.caso_numero}
                                                    </Typography>
                                                    <Typography variant="caption" color="textSecondary">
                                                        {selectedLog.caso_titulo}
                                                    </Typography>
                                                </Box>
                                            </Box>
                                        </Paper>
                                    </Grid>
                                )}

                                <Grid item xs={12} md={6}>
                                    <Typography variant="subtitle2" gutterBottom>
                                        Sesión
                                    </Typography>
                                    <Paper variant="outlined" sx={{ p: 2 }}>
                                        <Grid container spacing={1}>
                                            <Grid item xs={12}>
                                                <Typography variant="caption" color="textSecondary" display="block">
                                                    Duración
                                                </Typography>
                                                <Typography variant="body2">
                                                    {selectedLog.duracion_segundos ? formatDuration(selectedLog.duracion_segundos) : 'N/A'}
                                                </Typography>
                                            </Grid>
                                            <Grid item xs={12}>
                                                <Typography variant="caption" color="textSecondary" display="block">
                                                    Horario
                                                </Typography>
                                                <Typography variant="body2">
                                                    {moment(selectedLog.tiempo_inicio).format('HH:mm:ss')} - {moment(selectedLog.tiempo_fin).format('HH:mm:ss')}
                                                </Typography>
                                            </Grid>
                                        </Grid>
                                    </Paper>
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <Typography variant="subtitle2" gutterBottom>
                                        Información Técnica
                                    </Typography>
                                    <Paper variant="outlined" sx={{ p: 2 }}>
                                        <Grid container spacing={1}>
                                            <Grid item xs={12}>
                                                <Typography variant="caption" color="textSecondary" display="block">
                                                    Dirección IP
                                                </Typography>
                                                <Typography variant="body2" fontFamily="monospace">
                                                    {selectedLog.direccion_ip}
                                                </Typography>
                                            </Grid>
                                            <Grid item xs={12}>
                                                <Typography variant="caption" color="textSecondary" display="block">
                                                    User Agent
                                                </Typography>
                                                <Typography variant="body2" fontSize="0.75rem">
                                                    {selectedLog.user_agent}
                                                </Typography>
                                            </Grid>
                                        </Grid>
                                    </Paper>
                                </Grid>

                                {selectedLog.cambios && (
                                    <Grid item xs={12}>
                                        <Typography variant="subtitle2" gutterBottom>
                                            Cambios Realizados
                                        </Typography>
                                        <Paper variant="outlined" sx={{ p: 2, bgcolor: 'grey.50' }}>
                                            <Typography variant="body2" component="pre" sx={{
                                                whiteSpace: 'pre-wrap',
                                                wordBreak: 'break-word',
                                                fontFamily: 'monospace',
                                                fontSize: '0.75rem'
                                            }}>
                                                {selectedLog.cambios}
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                )}
                            </Grid>
                        </Box>
                    )}
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setLogDetailDialog(false)}>
                        Cerrar
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Diálogo para limpiar logs */}
            <Dialog open={deleteDialog} onClose={() => setDeleteDialog(false)}>
                <DialogTitle>Limpiar Logs Antiguos</DialogTitle>
                <DialogContent>
                    <Alert severity="warning" sx={{ mb: 2 }}>
                        Esta acción eliminará todos los logs con más de 90 días de antigüedad.
                    </Alert>
                    <Typography variant="body2">
                        ¿Está seguro de que desea proceder? Esta acción no se puede deshacer.
                    </Typography>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setDeleteDialog(false)}>
                        Cancelar
                    </Button>
                    <Button onClick={handleDeleteConfirm} color="error" variant="contained">
                        Limpiar Logs
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
};

export default ActivityLogs;
